    u32 local_24 = (u32)DSB(param_2 + 0x5Fu);
    if (local_24 == 0xFFu) { *eax = 0u; return; }
    fighter_anim_triple(anim, side, (s32)local_24);
    u32 bit = (mut & C2B7_EARLY) ? 0x4000u : 0x800u;
    if ((DSW(anim[2] + 2u) & bit) != 0u) { *eax = 0u; return; }
