    u32 ch = (mut & 32u) ? (u32)(s32)(s8)DSB(slot + 0x7Au) : (u32)DSB(slot + 0x7Au);   /* @csext */
    s32 thr = (mut & 1u) ? (s32)DSW(0x000BD870u + ch * 2u)              /* @thr: zero-extended */
                         : (s32)(s16)DSW(0x000BD870u + ch * 2u);
