    DSD(0x0010275Cu) = (mut & 8u) ? 0x00101544u : 0x0010153Cu;                 /* @free */
    if (!(mut & 16u)) DSD(0x00102754u) = 0u;                                   /* @last */
    if (!(mut & 32u)) DSD(0x00102758u) = 0u;                                   /* @l58 */
    if (mut & 64u) DSD(0x00105B44u) = 0u;              /* @head: the port before the correction */
