        actors_anim_begin(actor, DSD(((mut & 64u) ? 0x000C95BCu : 0x000C95D4u) + idx * 4u),   /* @tbl */
                          (mut & 128u) ? 0x40A00000u : 0x40400000u);     /* @hold */
