    if (mut & 0x8000u) { u32 w = bx; bx = by; by = w; }                   /* @ox */
    s32 ox = ((mut & 0x10000u) ? (s32)bx : (s32)(s8)bx) * ((mut & 0x20000u) ? 32 : 64);   /* @zext @shl */
    s32 oy = (s32)(s8)by * 64;
